{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a long-chain ester prodrug, had only 15% oral bioavailability in humans, an affirmative sub-20% result; this is the only direct low-F record and supports that lipophilic ester prodrugs can fall below the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "DINCH, a highly lipophilic diester with long alkyl chains, was almost completely bioavailable in humans; as the highest-transfer analogue, it would support high oral bioavailability if applied to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "DVAS, a dodecyl ester of a dipeptide, showed average 60% oral bioavailability in healthy volunteers; its long alkyl ester/amide motif is somewhat similar to the query's dodecyl N-formylleucine ester and supports high.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C30"],
      "claim": "Valomaciclovir stearate, a long-chain fatty ester prodrug, achieved >60% oral bioavailability in humans, indicating that fatty ester prodrugs can be well absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol palmitate, a long-chain palmitate ester prodrug, had absolute oral bioavailability of 85 ± 15% in children, another example of a lipophilic ester prodrug with high F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is orlistat, a beta-lactone lipase inhibitor designed for local gastrointestinal action; its reactive 2-oxetanone ring, extreme lipophilicity, and lack of ionizable groups lead to negligible systemic absorption (F < 20%). The only affirmative sub-20% evidence (laninamivir octanoate, 15%) is more consistent with this than the high-F ester prodrugs, which lack the beta-lactone liability.",
  "evidence_gaps": [
    "No direct orlistat or beta-lactone-containing analogue in the evidence set.",
    "All Morgan similarities are low (<0.25), limiting transferability.",
    "Most evidence comes from ester prodrugs with high oral bioavailability, not from non-absorbable lipase inhibitors.",
    "No human absolute bioavailability measurement for the query in the provided records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

